using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Taxonomies.DeleteTaxonomy;public sealed class DeleteTaxonomyCommandHandler(ITaxonomyTermRepository repo,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<DeleteTaxonomyCommand,Result>{public async Task<Result> HandleAsync(DeleteTaxonomyCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.TaxonomyNotFound);var before=ContentAuditSnapshots.From(x);x.Delete(c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.TaxonomyDeleted,ContentAuditActions.Deleted,ContentAuditEntityTypes.TaxonomyTerm,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);return Result.Success();}}
